      points: prices.length,
      current,
      allTimeLow: prices.length ? Math.min(...prices) : null,
      allTimeHigh: prices.length ? Math.max(...prices) : null,
      average: null,
      vsAveragePct: null,
      score: null,
      verdict: "unknown",
      headline: "Not enough recorded price history yet to score this deal. We never guess.",
      breakup: []
